    slug: "stc-คืออะไร",
    excerpt: "ทำความเข้าใจค่า STC (Sound Transmission Class) ค่ากันเสียงข้ามห้อง ต่างจาก NRC ยังไง และควรเลือกเท่าไหร่ให้เหมาะกับงานโครงการ",
    image: "/articles/article33.webp",
